WITH wave4_payload(document) AS (
  VALUES ('{"schema":"forensic-analysis-v1","as_of":"2026-07-29","generated_migration":"0038_exchange_wave4_forensic_analysis.sql","scope_note":"Wave 4 adds five non-overlapping exchange causal maps across Solana dynamic liquidity, Ethereum protocol-insured liquidity, a globally active custodial brand with entity-specific regulatory restructuring, a discontinued multichain AMM product, and a New Zealand CEX liquidation. Outcome labels match the public lifecycle cohorts. KyberSwap Elastic is scoped separately from KyberSwap''s active aggregator, the OKX case distinguishes the convicted Seychelles entity from the later U.S. platform, and Cryptopia trust-asset distributions are not misreported as recovery of hacked assets.","cases":[{"table":"successful_exchanges","kind":"dex","slug":"meteora","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"successful","summary":"Meteora remains a large operating Solana liquidity venue and token-launch infrastructure provider. The current adapter records about 3.88 billion dollars of 30-day DEX volume, 114.6 million dollars over 24 hours, and 324.9 billion dollars all time. Meteora''s Q1 2026 token-holder report separately records 19.53 billion dollars of quarterly volume, down 35.6 percent from Q4 2025. The sources use different windows and are not added together.","confidence":"high","as_of":"2026-07-29","source_refs":["https://api.llama.fi/summary/dexs/meteora?dataType=dailyVolume","https://ir.meteora.ag/assets/Meteora_Q1_2026_Token_Holder_Report.pdf","https://docs.meteora.ag/faq/how-do-i-create-a-new-farm"]},"why":{"summary":"Meteora combined bin-based concentrated liquidity and volatility-responsive fees with a broad launch stack spanning DLMM, DAMM and dynamic bonding curves. That made the protocol useful both after tokens reached open markets and during price discovery, giving launchpads and projects distribution incentives to integrate it. Solana''s low-cost, high-activity environment amplified this fit. Current volume and positive reported cash generation support success, while the Q1 contraction shows material dependence on Solana trading and token-launch cycles.","confidence":"medium","source_refs":["https://docs.meteora.ag/faq/how-do-i-create-a-new-farm","https://launch.meteora.ag/","https://ir.meteora.ag/assets/Meteora_Q1_2026_Token_Holder_Report.pdf","https://api.llama.fi/summary/dexs/meteora?dataType=dailyVolume"]},"strategic_choices":[{"decision":"Implement DLMM liquidity as discrete price bins with precise range selection and dynamic fees that respond to volatility.","consequence":"LPs can concentrate capital and charge more during volatile conditions, improving execution depth where liquidity is active while assuming active-range, inventory, parameter, and adverse-selection risk.","confidence":"high","source_refs":["https://docs.meteora.ag/faq/how-do-i-create-a-new-farm"]},{"decision":"Expand beyond secondary-market pools into DAMM and dynamic-bonding-curve launch infrastructure.","consequence":"Meteora can participate across token price discovery, migration, and ongoing liquidity, widening distribution and fee opportunities but tying activity to a volatile and reputationally risky token-launch market.","confidence":"high","source_refs":["https://launch.meteora.ag/","https://docs.meteora.ag/faq/how-do-i-create-a-new-farm"]},{"decision":"Concentrate the protocol and integrations on Solana rather than deploy a broad multichain contract footprint.","consequence":"One execution environment simplifies composability with Solana wallets, launchpads and routers, while leaving revenue and reliability exposed to one chain and its market cycle.","confidence":"high","source_refs":["https://launch.meteora.ag/","https://api.llama.fi/summary/dexs/meteora?dataType=dailyVolume"]},{"decision":"Use protocol revenue for treasury accumulation and measured MET buybacks after the token launch.","consequence":"The Q1 2026 report links operating activity to treasury runway and reports 7 million MET repurchased during the quarter, but token support remains dependent on recurring fees, treasury policy, and accurate protocol reporting.","confidence":"high","source_refs":["https://ir.meteora.ag/assets/Meteora_Q1_2026_Token_Holder_Report.pdf"]}],"counterfactual":{"summary":"A static-fee, full-range AMM would be simpler and easier for passive LPs to reason about, but would weaken Meteora''s differentiation during volatile Solana launches. Remaining only a secondary-market DEX would reduce launch-cycle and token-quality exposure, while surrendering a major integration and order-flow channel. The evidence supports the combined distribution thesis but cannot isolate how much volume each product created.","confidence":"medium","source_refs":["https://docs.meteora.ag/faq/how-do-i-create-a-new-farm","https://launch.meteora.ag/","https://api.llama.fi/summary/dexs/meteora?dataType=dailyVolume"]},"watch":[{"signal":"Thirty-day volume, fees, protocol revenue, treasury cash flow, and Solana DEX share.","implication":"Stable conversion of activity into cash supports durability; volume or fees falling faster than the wider Solana market would show moat erosion.","source_refs":["https://api.llama.fi/summary/dexs/meteora?dataType=dailyVolume","https://ir.meteora.ag/assets/Meteora_Q1_2026_Token_Holder_Report.pdf"]},{"signal":"Volume and fees split among DLMM, DAMM, DBC, launch partners, and recurring LP pools.","implication":"A diversified recurring base reduces launch-cycle risk; episodic partner or bonding-curve activity dominating economics makes results less predictable.","source_refs":["https://ir.meteora.ag/assets/Meteora_Q1_2026_Token_Holder_Report.pdf","https://launch.meteora.ag/"]},{"signal":"Pool incidents, program upgrades, admin authority, audit coverage, and realized LP performance net of inventory loss.","implication":"Secure upgrades and positive net LP results validate product complexity; losses that dynamic fees do not offset would impair liquidity retention.","source_refs":["https://github.com/MeteoraAg/dlmm-sdk/blob/main/CHANGELOG.md","https://docs.meteora.ag/faq/how-do-i-create-a-new-farm"]}],"unknowns":["What portion of Meteora volume would remain through a sustained contraction in Solana token launches and memecoin trading?","What is aggregate LP performance after loss-versus-rebalancing, out-of-range inventory, rebalancing cost, and incentives?","How concentrated are effective program upgrade authority, launch-partner order flow, and treasury control?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"mid_exchanges","kind":"dex","slug":"bancor","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"middling","summary":"Bancor remains technically active on Ethereum, with the current adapter reporting about 24.8 million dollars of TVL, but it operates far below its former scale and still carries the consequences of its 2022 liquidity-protection crisis. Governance discussions in 2025 and 2026 continue to track unresolved ETH and WBTC pool deficits. Middling means a live protocol and related Carbon development alongside impaired legacy LP claims, not a completed recovery.","confidence":"high","as_of":"2026-07-29","source_refs":["https://api.llama.fi/protocol/bancor","https://gov.bancor.network/t/ratification-of-emergency-actions-taken-on-sunday-19th-june-utc/3714","https://gov.bancor.network/t/wbtc-and-eth-deficit/4931","https://gov.bancor.network/t/four-years-later-what-has-actually-changed-on-the-deficit-and-what-comes-next/6953"]},"why":{"summary":"Bancor differentiated itself through single-sided liquidity and impermanent-loss protection funded by protocol BNT co-investment, fees, and an elastic token supply. The model promised simpler long-term LP exposure but underwrote market divergence with a reflexive asset. During June 2022 stress, deficits and pending withdrawals threatened runaway BNT issuance and price pressure, so emergency actions halted protection-related BNT minting and deposits. The intervention protected network continuity but converted an advertised protection mechanism into haircuts and long-lived deficits for affected pools.","confidence":"high","source_refs":["https://gov.bancor.network/t/proposing-bancor-v2-1-single-sided-amm-exposure-with-elastic-bnt-supply/35","https://gov.bancor.network/t/bip15-proposing-bancor-3/3445/48","https://gov.bancor.network/t/ratification-of-emergency-actions-taken-on-sunday-19th-june-utc/3714","https://api.llama.fi/protocol/bancor"]},"strategic_choices":[{"decision":"Offer single-sided LP exposure by minting protocol BNT as the counterpart asset in protected pools.","consequence":"Users avoided sourcing a second token and Bancor created a distinctive liquidity product, while the protocol and BNT holders absorbed correlated inventory and issuance risk.","confidence":"high","source_refs":["https://gov.bancor.network/t/proposing-bancor-v2-1-single-sided-amm-exposure-with-elastic-bnt-supply/35"]},{"decision":"Promise impermanent-loss protection funded by trading fees, protocol co-investment, and elastic BNT supply.","consequence":"Protection attracted long-duration liquidity in normal markets, but depended on fees and BNT economics covering divergence quickly enough; severe correlated withdrawals exposed that mismatch.","confidence":"high","source_refs":["https://gov.bancor.network/t/proposing-bancor-v2-1-single-sided-amm-exposure-with-elastic-bnt-supply/35","https://gov.bancor.network/t/bip9-proposing-the-bancor-vortex/354"]},{"decision":"Make Bancor 3 protection effectively immediate subject to withdrawal conditions rather than retain the earlier 100-day vesting schedule.","consequence":"The product became easier to understand and more attractive to LPs, but shortened the time available for fees to offset protection liabilities and increased sensitivity to synchronized exits.","confidence":"high","source_refs":["https://gov.bancor.network/t/bip15-proposing-bancor-3/3445/48"]},{"decision":"Halt BNT minting and restrict deposits during the June 2022 deficit instead of honoring protection through unconstrained issuance.","consequence":"The DAO reduced the risk of a BNT death spiral and preserved the protocol, while crystallizing withdrawal deficits and breaking the expected protection path for affected LPs.","confidence":"high","source_refs":["https://gov.bancor.network/t/ratification-of-emergency-actions-taken-on-sunday-19th-june-utc/3714"]}],"counterfactual":{"summary":"Hard coverage reserves, asset-specific protection caps, longer vesting, and automatic suspension before deficits became acute would likely have reduced synchronized claims and reflexive BNT issuance. Those controls would also make the headline protection less generous and could have reduced liquidity acquisition. A conventional unprotected AMM would avoid insurance insolvency but abandon Bancor''s central product distinction.","confidence":"medium","source_refs":["https://gov.bancor.network/t/proposing-bancor-v2-1-single-sided-amm-exposure-with-elastic-bnt-supply/35","https://gov.bancor.network/t/bip15-proposing-bancor-3/3445/48","https://gov.bancor.network/t/ratification-of-emergency-actions-taken-on-sunday-19th-june-utc/3714"]},"watch":[{"signal":"Pool-by-pool surplus or deficit, withdrawal haircuts, and affected LP distributions.","implication":"Sustained deficit reduction would support recovery; deficits persisting or widening keeps the legacy liability unresolved.","source_refs":["https://dune.com/bancor/bancor3-surplus-deficit","https://gov.bancor.network/t/wbtc-and-eth-deficit/4931"]},{"signal":"Bancor TVL, trading volume, fee income, and the share of liquidity that remains withdrawable without deficit.","implication":"Organic usage and liquid claims support a viable smaller protocol; capital that is present primarily because withdrawal is impaired overstates health.","source_refs":["https://api.llama.fi/protocol/bancor","https://gov.bancor.network/t/four-years-later-what-has-actually-changed-on-the-deficit-and-what-comes-next/6953"]},{"signal":"Carbon and protocol-owned-liquidity fees actually transferred toward deficit repair.","implication":"Auditable recurring transfers could create a recovery engine; product expansion without measurable claim repair would leave the core failure unresolved.","source_refs":["https://gov.bancor.network/t/proposal-to-use-pol-to-reduce-b3-deficits/4502","https://gov.bancor.network/t/four-years-later-what-has-actually-changed-on-the-deficit-and-what-comes-next/6953"]}],"unknowns":["What is the current token-denominated and dollar value of every Bancor 3 deficit using a documented, reproducible valuation date?","What percentage of impaired LP principal has been withdrawn, remains pending, or has recovered without subsidy?","How much net Carbon and Fast Lane revenue has reached deficit repair after operating and incentive costs?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"mid_exchanges","kind":"cex","slug":"okx","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"middling","summary":"The OKX brand remains a large operating global exchange and launched a phased U.S. platform in 2025, but the corpus case is scoped to the regulatory restructuring of Aux Cayes Fintech Co. Ltd., the Seychelles entity that pleaded guilty to operating an unlicensed U.S. money-transmitting business. OKX''s July 2026 proof-of-reserves page reports 23.12 billion dollars in primary assets. That self-reported, asset-scoped snapshot supports ongoing custody operations but is not proof of consolidated entity-wide solvency.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties","https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation","https://www.okx.com/es-la/proof-of-reserves"]},"why":{"summary":"OKX achieved global scale with a broad custodial spot and derivatives platform while its Seychelles operating entity allowed substantial U.S. access without required money-transmitter registration and adequate AML controls. Aux Cayes pleaded guilty in February 2025 and agreed to more than 504 million dollars in penalties. The brand then used the registered OKCoin footprint and a separately led U.S. rollout to re-enter through a different compliance structure. This is a costly entity and control failure followed by an operationally credible pivot, not a dead exchange.","confidence":"high","source_refs":["https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties","https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation","https://www.okx.com/es-la/proof-of-reserves"]},"strategic_choices":[{"decision":"Permit U.S.-located customers to access the offshore OKX platform without registering Aux Cayes as a U.S. money-services business.","consequence":"The entity captured U.S. activity but admitted criminal unlicensed-operation conduct and incurred more than 504 million dollars in forfeiture, fine, and related penalties.","confidence":"high","source_refs":["https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties"]},{"decision":"Use nominal U.S. restrictions while allowing customers to circumvent controls and delaying full KYC coverage.","consequence":"According to the DOJ''s account of court documents and admissions, the control environment did not match actual access, increasing illicit-finance exposure and making geographic terms ineffective.","confidence":"high","source_refs":["https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties"]},{"decision":"Launch a U.S. exchange and wallet through a regional headquarters and migrate existing OKCoin customers rather than restore offshore access.","consequence":"The brand preserved a path into the U.S. under a distinct product and leadership structure, while assuming migration, licensing, surveillance, and entity-separation costs.","confidence":"high","source_refs":["https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation"]},{"decision":"Publish monthly zk-STARK proof-of-reserves files, wallet addresses, and liability reports across an identified asset scope.","consequence":"Users can verify inclusion and compare disclosed assets with covered account balances, improving custody transparency while leaving fiat liabilities, corporate obligations, encumbrances, and cross-entity consolidation outside the cryptographic proof.","confidence":"high","source_refs":["https://www.okx.com/es-la/proof-of-reserves","https://www.okx.com/en-gb/proof-of-reserves/download"]}],"counterfactual":{"summary":"Effective geofencing, complete KYC before transaction access, early FinCEN registration analysis, and a licensed U.S. entity from the outset could plausibly have avoided the guilty plea and much of the penalty. Those controls would have slowed growth and excluded some users, but the later U.S. rollout demonstrates that entity-specific compliant access was operationally possible. It does not prove the earlier business would have had the same economics.","confidence":"medium","source_refs":["https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties","https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation"]},"watch":[{"signal":"Independent compliance reviews, monitor findings, enforcement follow-up, and separation between offshore and U.S. customer access.","implication":"Verified remediation supports a successful pivot; repeat control failures would show that the new entity structure is cosmetic.","source_refs":["https://www.justice.gov/usao-sdny/pr/okx-pleads-guilty-violating-us-anti-money-laundering-laws-and-agrees-pay-penalties","https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation"]},{"signal":"Monthly proof-of-reserves asset scope, liability methodology, reserve ratios, third-party custody, and report timeliness.","implication":"Broad timely coverage supports withdrawal confidence; scope reduction, stale files, or unverified third-party balances would weaken it.","source_refs":["https://www.okx.com/es-la/proof-of-reserves","https://www.okx.com/en-gb/proof-of-reserves/download"]},{"signal":"U.S. rollout coverage, product permissions, customer migration, and jurisdiction-specific legal-entity disclosures.","implication":"Transparent expansion through licensed entities validates restructuring; blurred product or entity claims recreate attribution and compliance risk.","source_refs":["https://www.okx.com/en-us/learn/bringing-okx-to-the-united-states-a-new-era-for-crypto-and-web3-innovation"]}],"unknowns":["What are consolidated assets, liabilities, encumbrances, and related-party exposures across all entities using the OKX brand?","What findings and remediation items remain open under post-plea compliance oversight?","How much U.S. activity migrated into the separately operated platform versus being permanently lost after offshore restrictions?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"dex","slug":"kyberswap","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"This case is strictly scoped to KyberSwap Elastic, the concentrated-liquidity AMM discontinued on November 23, 2023 after its exploit. It does not classify KyberSwap''s active aggregator, limit-order, cross-chain, or 2026 products as dead. KyberSwap reports that all affected users who applied received grants covering 100 percent of eligible affected funds, but compensation and the continued brand do not revive Elastic itself.","confidence":"high","as_of":"2026-07-29","source_refs":["https://docs.kyberswap.com/reference/legacy/kyberswap-elastic","https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/","https://docs.kyberswap.com/","https://blog.kyberswap.com/kyberswap-2026-product-updates/"]},"why":{"summary":"Elastic used proprietary tick-based concentrated liquidity, an investment curve, and an auto-compounding reinvestment curve. On November 22, 2023, a discrepancy between cross-tick estimation and final price calculation, amplified by double rounding, let precisely constructed swaps move price across a tick without updating base liquidity. Attackers extracted about 55.23 million dollars from affected pools and approximately 56.20 million dollars was taken or made inaccessible across 2,367 LP addresses. The flaw survived prior audits, and Kyber discontinued Elastic the next day rather than rebuild the same product.","confidence":"high","source_refs":["https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/","https://docs.kyberswap.com/reference/legacy/kyberswap-elastic","https://docs.kyberswap.com/reference/legacy/audits"]},"strategic_choices":[{"decision":"Develop a proprietary concentrated-liquidity AMM with separate investment and reinvestment curves for auto-compounded fees.","consequence":"Elastic differentiated LP returns and range control, but introduced interacting tick, price, rounding, and liquidity states beyond a simpler single-curve design.","confidence":"high","source_refs":["https://docs.kyberswap.com/reference/legacy/kyberswap-elastic","https://support.kyberswap.com/hc/en-us/articles/13766703722393-Is-KyberSwap-Elastic-a-fork-of-Uniswap-V3"]},{"decision":"Rely on numerical assumptions in computeSwapStep without enforcing consistency between the calculated final price, target tick, and liquidity update.","consequence":"A double-rounding edge case crossed the economic boundary without the corresponding state transition, enabling the attacker to make pool liquidity appear much larger than it was.","confidence":"high","source_refs":["https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/"]},{"decision":"Redeploy hardened Elastic contracts after a separate April 2023 whitehat disclosure and audits, then continue expanding the product.","consequence":"The first vulnerability was remediated without user loss, but confidence in review coverage proved incomplete when an unrelated critical swap-math flaw was exploited in November.","confidence":"high","source_refs":["https://docs.kyberswap.com/reference/legacy/kyberswap-elastic","https://docs.kyberswap.com/reference/legacy/audits"]},{"decision":"Discontinue Elastic and use the KyberSwap treasury to offer eligible users either faster partial grants or fully vested recovery.","consequence":"The decision contained repeat product risk and ultimately covered approved applicants, while imposing a major treasury cost and ending the AMM''s economic lifecycle.","confidence":"high","source_refs":["https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/","https://docs.kyberswap.com/reference/legacy/kyberswap-elastic"]}],"counterfactual":{"summary":"Explicit invariants requiring final price, current tick, crossed-tick status, and active liquidity to remain consistent after every swap step would likely have caught the exploitable state. Differential testing against high-precision arithmetic and adversarial fuzzing at amountSwapToCrossTick minus one could have exposed the double-rounding edge. The exact avoided loss still depends on deployment, monitoring, and pause timing.","confidence":"high","source_refs":["https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/","https://docs.kyberswap.com/reference/legacy/audits"]},"watch":[{"signal":"Any residual Elastic balances, late treasury-grant disputes, and additional asset recovery.","implication":"These determine final user and treasury cost but do not change the dead product classification unless Elastic is relaunched.","source_refs":["https://api.llama.fi/protocol/kyberswap-elastic","https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/"]},{"signal":"Whether new KyberSwap liquidity products reuse Elastic contracts, swap math, or only the surviving brand and aggregator.","implication":"Code reuse would carry relevant technical history into the new product; independent designs should be evaluated on their own controls.","source_refs":["https://docs.kyberswap.com/","https://blog.kyberswap.com/kyberswap-2026-product-updates/"]},{"signal":"Publication of formal verification properties, invariant tests, and incident-response controls for successor liquidity products.","implication":"Evidence that lessons changed engineering practice improves confidence in the active ecosystem, without retroactively reviving Elastic.","source_refs":["https://blog.kyberswap.com/post-mortem-kyberswap-elastic-exploit/","https://blog.kyberswap.com/kyberswap-2026-product-updates/"]}],"unknowns":["What was the final treasury cost of grants after recovered assets, vesting choices, and unsubmitted or ineligible claims?","What value remains in deprecated Elastic contracts, and how much is recoverable by rightful LPs?","Which specific testing and audit changes from the post-mortem are now mandatory for successor KyberSwap liquidity code?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"cryptopia","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Cryptopia has remained in liquidation since May 2019 and will not resume exchange operations. In December 2024, liquidators returned more than 400 million New Zealand dollars of Bitcoin and Dogecoin onchain to over 10,000 verified account holders. Those were surviving trust assets, not recovery of the approximately 30 million New Zealand dollars of cryptocurrency estimated stolen in the January 2019 hack. May 2026 court applications show that residual distributions and hack-loss treatment remain active liquidation matters.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.grantthornton.co.nz/press/press-releases-2019/cryptopia-limited-appoints-grant-thornton-as-liquidators/","https://www.grantthornton.co.nz/press/press-releases-2024/cryptopia-account-holders-receive-%24400m-from-liquidators/","https://www.grantthornton.co.nz/cryptopia/cryptopia-updates/update-for-cryptopia-claimants-and-stakeholders-15-may-2026/","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/cryptopia/2020/d.submissions-for-the-liquidators-23-january-2020.pdf"]},"why":{"summary":"Cryptopia ran a long-tail custodial exchange with hundreds of asset wallets and deficient reconciliation between onchain holdings and customer ledger balances. Attackers obtained private-key control and removed assets in January 2019; the source remains unidentified according to the liquidators. Cryptopia attempted to continue, but the hack severely damaged trading and the company could not return to profitability. Liquidation then required rebuilding wallet infrastructure, reconstructing transactions, proving claims, and obtaining court directions for asset-specific trusts.","confidence":"high","source_refs":["https://www.police.govt.nz/news/release/police-continue-make-progress-cryptocurrency-investigation","https://www.grantthornton.co.nz/press/press-releases-2019/cryptopia-limited-appoints-grant-thornton-as-liquidators/","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/11th-liquidators-report_cryptopia_june-24_final.pdf","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/cryptopia/2020/d.submissions-for-the-liquidators-23-january-2020.pdf"]},"strategic_choices":[{"decision":"List and custody a very large number of long-tail cryptocurrencies through exchange-controlled wallet infrastructure.","consequence":"The catalog attracted a broad user base, but multiplied key-management, node, wallet, reconciliation, low-value-asset, and incident-recovery complexity.","confidence":"medium","source_refs":["https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/cryptopia/2020/d.submissions-for-the-liquidators-23-january-2020.pdf","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/11th-liquidators-report_cryptopia_june-24_final.pdf"]},{"decision":"Operate without a completed recurring reconciliation between actual wallet assets and customer balances.","consequence":"After liquidation, administrators had to reconstruct wallets and millions of transactions before entitlements could be calculated, extending cost and recovery time.","confidence":"high","source_refs":["https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/cryptopia/2020/d.submissions-for-the-liquidators-23-january-2020.pdf","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/11th-liquidators-report_cryptopia_june-24_final.pdf"]},{"decision":"Attempt to restore operations and profitability after the January 2019 hack before entering liquidation in May.","consequence":"Management preserved a chance of continuation, but the hack''s trading impact and operating costs proved too severe, delaying the shift to an insolvency-led recovery process.","confidence":"high","source_refs":["https://www.grantthornton.co.nz/press/press-releases-2019/cryptopia-limited-appoints-grant-thornton-as-liquidators/"]},{"decision":"Pursue court-supervised, in-specie trust distributions with identity and wallet verification rather than pool all surviving assets as ordinary corporate property.","consequence":"Verified users could receive the cryptocurrency attributable to their asset trusts, including the large 2024 distribution, while the asset-by-asset model required years of portal, reconciliation, cutoff, and court work.","confidence":"high","source_refs":["https://www.grantthornton.co.nz/press/press-releases-2024/cryptopia-account-holders-receive-%24400m-from-liquidators/","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/f20240301-sealed-orders-for-distribution-of-cryptocurrencies.pdf"]}],"counterfactual":{"summary":"Per-asset wallet-to-ledger reconciliation, segmented cold storage, stronger key isolation, withdrawal anomaly detection, and tested compromise recovery would likely have reduced loss and dramatically simplified administration. A narrower listing catalog could also reduce wallet attack surface. Public evidence does not identify the attacker or exact entry path, so no single control can be claimed to have prevented the hack.","confidence":"medium","source_refs":["https://www.police.govt.nz/news/release/update-investigation-involving-cryptocurrency-company","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/11th-liquidators-report_cryptopia_june-24_final.pdf","https://www.grantthornton.co.nz/globalassets/1.-member-firms/new-zealand/pdfs/cryptopia/2020/d.submissions-for-the-liquidators-23-january-2020.pdf"]},"watch":[{"signal":"High Court decisions on hack liability, late claims, unclaimed trust assets, and top-up authority.","implication":"The decisions determine eligible claimants and final recovery mechanics, but cannot revive the liquidated exchange.","source_refs":["https://www.grantthornton.co.nz/cryptopia/cryptopia-updates/update-for-cryptopia-claimants-and-stakeholders-15-may-2026/"]},{"signal":"Further distributions by asset, number of verified recipients, administration cost, and completion date.","implication":"Higher distributions and closure improve realized recovery; continued delay and cost reduce the value of surviving holdings.","source_refs":["https://www.grantthornton.co.nz/cryptopia/cryptopia-updates//","https://www.grantthornton.co.nz/press/press-releases-2024/cryptopia-account-holders-receive-%24400m-from-liquidators/"]},{"signal":"Any law-enforcement identification, freeze, or recovery of assets stolen in the January 2019 hack.","implication":"Hack-asset recovery could increase unsecured creditor outcomes; it must remain separate from distribution of assets that were never stolen.","source_refs":["https://www.police.govt.nz/news/release/police-continue-make-progress-cryptocurrency-investigation","https://www.grantthornton.co.nz/cryptopia/cryptopia-updates/update-for-cryptopia-claimants-and-stakeholders-15-may-2026/"]}],"unknowns":["What final percentage of pre-hack balances will each asset trust and hack-loss creditor class receive after all costs and court orders?","Who caused the January 2019 compromise, which keys or systems failed, and how much stolen cryptocurrency remains traceable?","What total professional and technical cost will the seven-plus-year liquidation consume before every viable trust is closed?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}]}')
)
INSERT OR REPLACE INTO exchange_wave4_forensic_0038 (target_table, kind, slug, analysis)
SELECT
  json_extract(value, '$.table'),
  json_extract(value, '$.kind'),
  json_extract(value, '$.slug'),
  json_extract(value, '$.forensic_analysis')
FROM wave4_payload, json_each(wave4_payload.document, '$.cases');
-- canonical-payload-end

UPDATE successful_exchanges
SET profile = json_set(
      COALESCE(NULLIF(profile, ''), '{}'),
      '$.forensic_analysis',
      json((
        SELECT analysis
        FROM exchange_wave4_forensic_0038 AS wave
        WHERE wave.target_table = 'successful_exchanges'
          AND wave.kind = successful_exchanges.type
          AND wave.slug = successful_exchanges.slug
      ))
    ),
    updated_at = '2026-07-29'
WHERE EXISTS (
  SELECT 1
  FROM exchange_wave4_forensic_0038 AS wave
  WHERE wave.target_table = 'successful_exchanges'
    AND wave.kind = successful_exchanges.type
    AND wave.slug = successful_exchanges.slug
);

